-- Упражнения книги 17, глава 24 (oVirt). Файл строит scratchpad/ovirt/builder.py; после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-backup-scope', 0, 'func', 'Что покрыли копии', 'Утилита engine-backup делает копию по области (scope). Правила модели: scope ''all'' покрывает ресурсы ''engine_db'', ''engine_files'' и ''dwh_db''; scope ''files'' — только ''engine_files''; scope ''db'' — только ''engine_db''; scope ''dwhdb'' — только ''dwh_db''. Неизвестные области ничего не покрывают. Напишите функцию uncovered(required, scopes): required — список ресурсов, которые нужно защитить (среди них могут быть и такие, которых не покрывает ни одна область, например ''vm_disks''), scopes — список областей, по которым сделаны копии. Верните отсортированный список требуемых ресурсов, не покрытых ни одной копией, без повторов.', 'def uncovered(required, scopes):
    pass
', 'Соберите множество покрытого через словарь «область → множество ресурсов», затем вычтите его из множества required.', '{"func": "uncovered", "tests": [{"args": [["engine_db", "engine_files"], ["all"]], "expected": []}, {"args": [["engine_db", "engine_files", "dwh_db", "vm_disks"], ["db", "files"]], "expected": ["dwh_db", "vm_disks"]}, {"args": [["vm_disks"], ["all"]], "expected": ["vm_disks"]}, {"args": [[], ["all"]], "expected": []}, {"args": [["engine_db", "engine_db", "dwh_db"], []], "expected": ["dwh_db", "engine_db"]}, {"args": [["engine_files", "dwh_db"], ["dwhdb", "bogus"]], "expected": ["engine_files"]}, {"args": [["dwh_db", "engine_db"], ["files", "files"]], "expected": ["dwh_db", "engine_db"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-backup-log', 1, 'func', 'Итог по журналу копии', 'Журнал engine-backup состоит из строк вида ''<дата> <время> <УРОВЕНЬ>: <сообщение>'', например ''2026-03-01 02:00:01 INFO: Done.''. Уровни — INFO:, WARNING:, ERROR:. Строка, у которой нет четырёх частей через пробел (дата, время, уровень, сообщение) или уровень другой, игнорируется. Напишите функцию backup_status(lines): верните кортеж (статус, число WARNING, число ERROR). Статус ''failed'', если была хотя бы одна строка ERROR; иначе ''ok'', если сообщение последней учтённой строки равно ''Done.''; иначе ''incomplete''. Пустой журнал даёт (''incomplete'', 0, 0).', 'def backup_status(lines):
    pass
', 'line.split('' '', 3) даёт дату, время, уровень и остаток-сообщение; последнюю учтённую строку запоминайте в цикле.', '{"func": "backup_status", "tests": [{"args": [["2026-03-01 02:00:01 INFO: Start of engine-backup with mode ''backup''", "2026-03-01 02:00:02 INFO: Backing up database engine", "2026-03-01 02:03:10 INFO: Done."]], "expected": {"__tuple__": ["ok", 0, 0]}}, {"args": [["2026-03-01 02:00:01 INFO: Start", "2026-03-01 02:00:05 WARNING: dwh database not found", "garbage line", "", "2026-03-01 02:00:09 INFO: Done."]], "expected": {"__tuple__": ["ok", 1, 0]}}, {"args": [["2026-03-01 02:00:01 INFO: Start", "2026-03-01 02:00:05 ERROR: pg_dump failed", "2026-03-01 02:00:06 INFO: Done."]], "expected": {"__tuple__": ["failed", 0, 1]}}, {"args": [["2026-03-01 02:00:01 INFO: Start", "2026-03-01 02:00:02 INFO: Backing up database engine"]], "expected": {"__tuple__": ["incomplete", 0, 0]}}, {"args": [[]], "expected": {"__tuple__": ["incomplete", 0, 0]}}, {"args": [["2026-03-01 02:00:01 DEBUG: Done."]], "expected": {"__tuple__": ["incomplete", 0, 0]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-snapshot-chain', 2, 'func', 'Рост цепочки снимков', 'Модель цепочки слоёв диска. Сначала есть один базовый слой размера 0 (индекс 0). Операции: [''write'', n] — записать n МБ в верхний слой (слои растут); [''snapshot''] — добавить новый пустой верхний слой; [''delete'', i] — удалить снимок i: если 1 <= i < числа слоёв, размер слоя i прибавляется к слою i-1 (слияние вниз), а слой i исчезает; иначе операция игнорируется (базовый слой удалить нельзя). Напишите функцию chain_after(ops): верните список размеров слоёв от базового к верхнему после всех операций по порядку.', 'def chain_after(ops):
    pass
', 'Список размеров layers; запись — layers[-1] += n; удаление — layers[i-1] += layers[i]; del layers[i].', '{"func": "chain_after", "tests": [{"args": [[]], "expected": [0]}, {"args": [[["write", 100]]], "expected": [100]}, {"args": [[["write", 100], ["snapshot"], ["write", 20], ["snapshot"], ["write", 5]]], "expected": [100, 20, 5]}, {"args": [[["write", 100], ["snapshot"], ["write", 20], ["snapshot"], ["write", 5], ["delete", 1]]], "expected": [120, 5]}, {"args": [[["write", 10], ["snapshot"], ["write", 3], ["delete", 0], ["delete", 7], ["delete", 1], ["write", 4]]], "expected": [17]}, {"args": [[["snapshot"], ["snapshot"], ["snapshot"], ["write", 1], ["delete", 3], ["delete", 2], ["delete", 1]]], "expected": [1]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-snapshot-kind', 3, 'func', 'Согласованность снимка', 'Модель снимка. Параметры: vm_up (машина включена), agent (гостевой агент работает), quiesce (запрошена заморозка файловых систем), memory (запрошено сохранение памяти). Правила. Если машина выключена, вид снимка ''offline'', восстановление работающего состояния невозможно. Если включена и quiesce запрошена и агент работает — вид ''application''. Иначе вид ''crash''; если при этом quiesce была запрошена (агента нет), в список предупреждений попадает ''quiesce_skipped''. Для включённой машины восстановление работающего состояния возможно тогда и только тогда, когда memory истинно. Напишите функцию snapshot_kind(vm_up, agent, quiesce, memory): верните кортеж (вид, можно_ли_восстановить_работающее_состояние, список предупреждений).', 'def snapshot_kind(vm_up, agent, quiesce, memory):
    pass
', 'Сначала разберите выключенную машину, потом условие quiesce and agent; булево memory возвращайте как есть.', '{"func": "snapshot_kind", "tests": [{"args": [true, true, true, false], "expected": {"__tuple__": ["application", false, []]}}, {"args": [true, true, true, true], "expected": {"__tuple__": ["application", true, []]}}, {"args": [true, false, true, false], "expected": {"__tuple__": ["crash", false, ["quiesce_skipped"]]}}, {"args": [true, false, false, true], "expected": {"__tuple__": ["crash", true, []]}}, {"args": [true, true, false, false], "expected": {"__tuple__": ["crash", false, []]}}, {"args": [false, true, true, true], "expected": {"__tuple__": ["offline", false, []]}}, {"args": [false, false, false, false], "expected": {"__tuple__": ["offline", false, []]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-dirty-blocks', 4, 'func', 'Какие блоки копировать', 'Модель битовых карт изменений. Журнал событий диска events — список: [''write'', b] (записан блок b), [''checkpoint'', имя] (создана контрольная точка; имена уникальны) и [''reset''] (карты изменений потеряны, например диск был подменён). Напишите функцию blocks_to_copy(events, num_blocks, from_checkpoint). Если from_checkpoint равен None, это полная копия: верните список всех номеров блоков от 0 до num_blocks-1. Иначе это инкрементальная копия: верните отсортированный список без повторов блоков, записанных после события контрольной точки с этим именем (учитывайте только блоки 0 <= b < num_blocks). Если такой точки нет в журнале или после неё произошёл reset, инкрементальная копия невозможна — верните None.', 'def blocks_to_copy(events, num_blocks, from_checkpoint):
    pass
', 'Найдите индекс события контрольной точки, затем пройдите по хвосту: reset сразу даёт None, write добавляет блок в множество.', '{"func": "blocks_to_copy", "tests": [{"args": [[["write", 1], ["checkpoint", "cp1"], ["write", 3], ["write", 5], ["checkpoint", "cp2"], ["write", 3], ["write", 0]], 8, null], "expected": [0, 1, 2, 3, 4, 5, 6, 7]}, {"args": [[["write", 1], ["checkpoint", "cp1"], ["write", 3], ["write", 5], ["checkpoint", "cp2"], ["write", 3], ["write", 0]], 8, "cp1"], "expected": [0, 3, 5]}, {"args": [[["write", 1], ["checkpoint", "cp1"], ["write", 3], ["write", 5], ["checkpoint", "cp2"], ["write", 3], ["write", 0]], 8, "cp2"], "expected": [0, 3]}, {"args": [[["write", 1], ["checkpoint", "cp1"], ["write", 3], ["write", 5], ["checkpoint", "cp2"], ["write", 3], ["write", 0]], 8, "cp9"], "expected": null}, {"args": [[["write", 1], ["checkpoint", "cp1"], ["write", 3], ["write", 5], ["checkpoint", "cp2"], ["write", 3], ["write", 0]], 4, "cp1"], "expected": [0, 3]}, {"args": [[["write", 2], ["checkpoint", "a"], ["reset"], ["write", 1]], 4, "a"], "expected": null}, {"args": [[["write", 2], ["reset"], ["checkpoint", "a"], ["write", 1], ["write", 1]], 4, "a"], "expected": [1]}, {"args": [[["checkpoint", "a"]], 3, "a"], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-restore-chain', 5, 'func', 'Восстановление из цепочки', 'Цепочка резервных копий диска chain — список элементов [имя, вид, блоки] в порядке создания. Вид — ''full'' или ''inc''; блоки — словарь «имя блока → содержимое» (строки). У инкрементальной копии значение None означает, что блок снова пуст (его нужно убрать из результата). Напишите функцию restore(chain, point): верните словарь с содержимым диска на момент копии с именем point. Для этого найдите последнюю полную копию не позже point и по порядку наложите её и все следующие копии до point включительно. Если копии с именем point нет или перед ней нет полной копии, верните None.', 'def restore(chain, point):
    pass
', 'Найдите индекс point, пройдите назад до ''full'', затем накладывайте словари через update; None — это pop.', '{"func": "restore", "tests": [{"args": [[["b1", "full", {"blk0": "a1", "blk1": "b1", "blk2": "c1"}], ["b2", "inc", {"blk1": "b2"}], ["b3", "inc", {"blk2": null, "blk3": "d3"}], ["b4", "full", {"blk0": "a4", "blk1": "b4"}], ["b5", "inc", {"blk0": "a5"}]], "b1"], "expected": {"blk0": "a1", "blk1": "b1", "blk2": "c1"}}, {"args": [[["b1", "full", {"blk0": "a1", "blk1": "b1", "blk2": "c1"}], ["b2", "inc", {"blk1": "b2"}], ["b3", "inc", {"blk2": null, "blk3": "d3"}], ["b4", "full", {"blk0": "a4", "blk1": "b4"}], ["b5", "inc", {"blk0": "a5"}]], "b2"], "expected": {"blk0": "a1", "blk1": "b2", "blk2": "c1"}}, {"args": [[["b1", "full", {"blk0": "a1", "blk1": "b1", "blk2": "c1"}], ["b2", "inc", {"blk1": "b2"}], ["b3", "inc", {"blk2": null, "blk3": "d3"}], ["b4", "full", {"blk0": "a4", "blk1": "b4"}], ["b5", "inc", {"blk0": "a5"}]], "b3"], "expected": {"blk0": "a1", "blk1": "b2", "blk3": "d3"}}, {"args": [[["b1", "full", {"blk0": "a1", "blk1": "b1", "blk2": "c1"}], ["b2", "inc", {"blk1": "b2"}], ["b3", "inc", {"blk2": null, "blk3": "d3"}], ["b4", "full", {"blk0": "a4", "blk1": "b4"}], ["b5", "inc", {"blk0": "a5"}]], "b4"], "expected": {"blk0": "a4", "blk1": "b4"}}, {"args": [[["b1", "full", {"blk0": "a1", "blk1": "b1", "blk2": "c1"}], ["b2", "inc", {"blk1": "b2"}], ["b3", "inc", {"blk2": null, "blk3": "d3"}], ["b4", "full", {"blk0": "a4", "blk1": "b4"}], ["b5", "inc", {"blk0": "a5"}]], "b5"], "expected": {"blk0": "a5", "blk1": "b4"}}, {"args": [[["b1", "full", {"blk0": "a1", "blk1": "b1", "blk2": "c1"}], ["b2", "inc", {"blk1": "b2"}], ["b3", "inc", {"blk2": null, "blk3": "d3"}], ["b4", "full", {"blk0": "a4", "blk1": "b4"}], ["b5", "inc", {"blk0": "a5"}]], "b9"], "expected": null}, {"args": [[["x1", "inc", {"blk0": "z"}], ["x2", "full", {"blk1": "y"}]], "x1"], "expected": null}, {"args": [[], "b1"], "expected": null}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-restorable', 6, 'func', 'Какие копии ещё можно восстановить', 'У каждой копии есть пара [from, to]: from — контрольная точка, от которой считались изменения (None у полной копии), to — контрольная точка, созданная этой копией (значения to уникальны). Копия восстановима, если она полная, либо её from равна to какой-то копии, которая ещё есть в словаре и сама восстановима. Копия, чья родительская копия удалена, а также копии в цикле не восстановимы. Напишите функцию restorable(backups): backups — словарь «идентификатор копии → [from, to]»; верните отсортированный список идентификаторов восстановимых копий.', 'def restorable(backups):
    pass
', 'Постройте словарь «to → идентификатор» и рекурсивно поднимайтесь по from; следите за посещёнными, чтобы не зациклиться.', '{"func": "restorable", "tests": [{"args": [{}], "expected": []}, {"args": [{"a": [null, "c1"], "b": ["c1", "c2"], "c": ["c2", "c3"]}], "expected": ["a", "b", "c"]}, {"args": [{"b": ["c1", "c2"], "c": ["c2", "c3"]}], "expected": []}, {"args": [{"a": [null, "c1"], "c": ["c2", "c3"]}], "expected": ["a"]}, {"args": [{"a": [null, "c1"], "b": ["c1", "c2"], "f": [null, "c5"], "g": ["c5", "c6"], "h": ["c9", "c7"]}], "expected": ["a", "b", "f", "g"]}, {"args": [{"x": ["c2", "c1"], "y": ["c1", "c2"]}], "expected": []}, {"args": [{"s": ["c1", "c1"]}], "expected": []}, {"args": [{"a": [null, "c1"], "b": ["c1", "c2"], "c": ["c1", "c3"], "d": ["c3", "c4"]}], "expected": ["a", "b", "c", "d"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-retention', 7, 'func', 'Хранение дед-отец-сын', 'Копии заданы списком [id, день, родитель], день — целое число (номер дня), родитель — id предыдущей копии цепочки или None у полной копии. Политика хранения при текущем дне today: (1) дневные: оставить копии с today - день < daily; (2) недельные: неделя копии — день // 7; для каждой из последних weekly недель (таких, что today // 7 - неделя < weekly) оставить самую позднюю по дню копию недели (при равных днях — более позднюю в списке); (3) месячные: так же, но месяц — день // 30 и последние monthly месяцев. (4) Копия, которую оставили, тянет за собой всех своих предков по цепочке родителей — их тоже нельзя удалять. Напишите функцию prune(backups, today, daily, weekly, monthly): верните отсортированный список id копий, которые остаются. Родитель, которого нет в списке, просто пропускается.', 'def prune(backups, today, daily, weekly, monthly):
    pass
', 'Сначала соберите множество keep по трём правилам, потом для каждой оставленной копии поднимайтесь по родителям и добавляйте их.', '{"func": "prune", "tests": [{"args": [[["b0", 0, null], ["b1", 1, "b0"], ["b2", 2, "b1"], ["b3", 3, "b2"], ["b4", 4, "b3"], ["b5", 5, "b4"], ["b6", 6, "b5"], ["b7", 7, "b6"], ["b8", 8, "b7"], ["b9", 9, "b8"], ["b10", 10, null], ["b11", 11, "b10"], ["b12", 12, "b11"], ["b13", 13, "b12"], ["b14", 14, "b13"], ["b15", 15, "b14"], ["b16", 16, "b15"], ["b17", 17, "b16"], ["b18", 18, "b17"], ["b19", 19, "b18"], ["b20", 20, null], ["b21", 21, "b20"], ["b22", 22, "b21"], ["b23", 23, "b22"], ["b24", 24, "b23"], ["b25", 25, "b24"], ["b26", 26, "b25"], ["b27", 27, "b26"], ["b28", 28, "b27"], ["b29", 29, "b28"], ["b30", 30, null], ["b31", 31, "b30"], ["b32", 32, "b31"], ["b33", 33, "b32"], ["b34", 34, "b33"], ["b35", 35, "b34"], ["b36", 36, "b35"], ["b37", 37, "b36"], ["b38", 38, "b37"], ["b39", 39, "b38"], ["b40", 40, null], ["b41", 41, "b40"], ["b42", 42, "b41"], ["b43", 43, "b42"], ["b44", 44, "b43"], ["b45", 45, "b44"]], 45, 0, 0, 0], "expected": []}, {"args": [[["b0", 0, null], ["b1", 1, "b0"], ["b2", 2, "b1"], ["b3", 3, "b2"], ["b4", 4, "b3"], ["b5", 5, "b4"], ["b6", 6, "b5"], ["b7", 7, "b6"], ["b8", 8, "b7"], ["b9", 9, "b8"], ["b10", 10, null], ["b11", 11, "b10"], ["b12", 12, "b11"], ["b13", 13, "b12"], ["b14", 14, "b13"], ["b15", 15, "b14"], ["b16", 16, "b15"], ["b17", 17, "b16"], ["b18", 18, "b17"], ["b19", 19, "b18"], ["b20", 20, null], ["b21", 21, "b20"], ["b22", 22, "b21"], ["b23", 23, "b22"], ["b24", 24, "b23"], ["b25", 25, "b24"], ["b26", 26, "b25"], ["b27", 27, "b26"], ["b28", 28, "b27"], ["b29", 29, "b28"], ["b30", 30, null], ["b31", 31, "b30"], ["b32", 32, "b31"], ["b33", 33, "b32"], ["b34", 34, "b33"], ["b35", 35, "b34"], ["b36", 36, "b35"], ["b37", 37, "b36"], ["b38", 38, "b37"], ["b39", 39, "b38"], ["b40", 40, null], ["b41", 41, "b40"], ["b42", 42, "b41"], ["b43", 43, "b42"], ["b44", 44, "b43"], ["b45", 45, "b44"]], 45, 3, 0, 0], "expected": ["b40", "b41", "b42", "b43", "b44", "b45"]}, {"args": [[["b0", 0, null], ["b1", 1, "b0"], ["b2", 2, "b1"], ["b3", 3, "b2"], ["b4", 4, "b3"], ["b5", 5, "b4"], ["b6", 6, "b5"], ["b7", 7, "b6"], ["b8", 8, "b7"], ["b9", 9, "b8"], ["b10", 10, null], ["b11", 11, "b10"], ["b12", 12, "b11"], ["b13", 13, "b12"], ["b14", 14, "b13"], ["b15", 15, "b14"], ["b16", 16, "b15"], ["b17", 17, "b16"], ["b18", 18, "b17"], ["b19", 19, "b18"], ["b20", 20, null], ["b21", 21, "b20"], ["b22", 22, "b21"], ["b23", 23, "b22"], ["b24", 24, "b23"], ["b25", 25, "b24"], ["b26", 26, "b25"], ["b27", 27, "b26"], ["b28", 28, "b27"], ["b29", 29, "b28"], ["b30", 30, null], ["b31", 31, "b30"], ["b32", 32, "b31"], ["b33", 33, "b32"], ["b34", 34, "b33"], ["b35", 35, "b34"], ["b36", 36, "b35"], ["b37", 37, "b36"], ["b38", 38, "b37"], ["b39", 39, "b38"], ["b40", 40, null], ["b41", 41, "b40"], ["b42", 42, "b41"], ["b43", 43, "b42"], ["b44", 44, "b43"], ["b45", 45, "b44"]], 45, 0, 2, 0], "expected": ["b40", "b41", "b42", "b43", "b44", "b45"]}, {"args": [[["b0", 0, null], ["b1", 1, "b0"], ["b2", 2, "b1"], ["b3", 3, "b2"], ["b4", 4, "b3"], ["b5", 5, "b4"], ["b6", 6, "b5"], ["b7", 7, "b6"], ["b8", 8, "b7"], ["b9", 9, "b8"], ["b10", 10, null], ["b11", 11, "b10"], ["b12", 12, "b11"], ["b13", 13, "b12"], ["b14", 14, "b13"], ["b15", 15, "b14"], ["b16", 16, "b15"], ["b17", 17, "b16"], ["b18", 18, "b17"], ["b19", 19, "b18"], ["b20", 20, null], ["b21", 21, "b20"], ["b22", 22, "b21"], ["b23", 23, "b22"], ["b24", 24, "b23"], ["b25", 25, "b24"], ["b26", 26, "b25"], ["b27", 27, "b26"], ["b28", 28, "b27"], ["b29", 29, "b28"], ["b30", 30, null], ["b31", 31, "b30"], ["b32", 32, "b31"], ["b33", 33, "b32"], ["b34", 34, "b33"], ["b35", 35, "b34"], ["b36", 36, "b35"], ["b37", 37, "b36"], ["b38", 38, "b37"], ["b39", 39, "b38"], ["b40", 40, null], ["b41", 41, "b40"], ["b42", 42, "b41"], ["b43", 43, "b42"], ["b44", 44, "b43"], ["b45", 45, "b44"]], 45, 0, 3, 0], "expected": ["b30", "b31", "b32", "b33", "b34", "b40", "b41", "b42", "b43", "b44", "b45"]}, {"args": [[["b0", 0, null], ["b1", 1, "b0"], ["b2", 2, "b1"], ["b3", 3, "b2"], ["b4", 4, "b3"], ["b5", 5, "b4"], ["b6", 6, "b5"], ["b7", 7, "b6"], ["b8", 8, "b7"], ["b9", 9, "b8"], ["b10", 10, null], ["b11", 11, "b10"], ["b12", 12, "b11"], ["b13", 13, "b12"], ["b14", 14, "b13"], ["b15", 15, "b14"], ["b16", 16, "b15"], ["b17", 17, "b16"], ["b18", 18, "b17"], ["b19", 19, "b18"], ["b20", 20, null], ["b21", 21, "b20"], ["b22", 22, "b21"], ["b23", 23, "b22"], ["b24", 24, "b23"], ["b25", 25, "b24"], ["b26", 26, "b25"], ["b27", 27, "b26"], ["b28", 28, "b27"], ["b29", 29, "b28"], ["b30", 30, null], ["b31", 31, "b30"], ["b32", 32, "b31"], ["b33", 33, "b32"], ["b34", 34, "b33"], ["b35", 35, "b34"], ["b36", 36, "b35"], ["b37", 37, "b36"], ["b38", 38, "b37"], ["b39", 39, "b38"], ["b40", 40, null], ["b41", 41, "b40"], ["b42", 42, "b41"], ["b43", 43, "b42"], ["b44", 44, "b43"], ["b45", 45, "b44"]], 45, 0, 0, 1], "expected": ["b40", "b41", "b42", "b43", "b44", "b45"]}, {"args": [[["b0", 0, null], ["b1", 1, "b0"], ["b2", 2, "b1"], ["b3", 3, "b2"], ["b4", 4, "b3"], ["b5", 5, "b4"], ["b6", 6, "b5"], ["b7", 7, "b6"], ["b8", 8, "b7"], ["b9", 9, "b8"], ["b10", 10, null], ["b11", 11, "b10"], ["b12", 12, "b11"], ["b13", 13, "b12"], ["b14", 14, "b13"], ["b15", 15, "b14"], ["b16", 16, "b15"], ["b17", 17, "b16"], ["b18", 18, "b17"], ["b19", 19, "b18"], ["b20", 20, null], ["b21", 21, "b20"], ["b22", 22, "b21"], ["b23", 23, "b22"], ["b24", 24, "b23"], ["b25", 25, "b24"], ["b26", 26, "b25"], ["b27", 27, "b26"], ["b28", 28, "b27"], ["b29", 29, "b28"], ["b30", 30, null], ["b31", 31, "b30"], ["b32", 32, "b31"], ["b33", 33, "b32"], ["b34", 34, "b33"], ["b35", 35, "b34"], ["b36", 36, "b35"], ["b37", 37, "b36"], ["b38", 38, "b37"], ["b39", 39, "b38"], ["b40", 40, null], ["b41", 41, "b40"], ["b42", 42, "b41"], ["b43", 43, "b42"], ["b44", 44, "b43"], ["b45", 45, "b44"]], 45, 0, 0, 2], "expected": ["b20", "b21", "b22", "b23", "b24", "b25", "b26", "b27", "b28", "b29", "b40", "b41", "b42", "b43", "b44", "b45"]}, {"args": [[["b0", 0, null], ["b1", 1, "b0"], ["b2", 2, "b1"], ["b3", 3, "b2"], ["b4", 4, "b3"], ["b5", 5, "b4"], ["b6", 6, "b5"], ["b7", 7, "b6"], ["b8", 8, "b7"], ["b9", 9, "b8"], ["b10", 10, null], ["b11", 11, "b10"], ["b12", 12, "b11"], ["b13", 13, "b12"], ["b14", 14, "b13"], ["b15", 15, "b14"], ["b16", 16, "b15"], ["b17", 17, "b16"], ["b18", 18, "b17"], ["b19", 19, "b18"], ["b20", 20, null], ["b21", 21, "b20"], ["b22", 22, "b21"], ["b23", 23, "b22"], ["b24", 24, "b23"], ["b25", 25, "b24"], ["b26", 26, "b25"], ["b27", 27, "b26"], ["b28", 28, "b27"], ["b29", 29, "b28"], ["b30", 30, null], ["b31", 31, "b30"], ["b32", 32, "b31"], ["b33", 33, "b32"], ["b34", 34, "b33"], ["b35", 35, "b34"], ["b36", 36, "b35"], ["b37", 37, "b36"], ["b38", 38, "b37"], ["b39", 39, "b38"], ["b40", 40, null], ["b41", 41, "b40"], ["b42", 42, "b41"], ["b43", 43, "b42"], ["b44", 44, "b43"], ["b45", 45, "b44"]], 45, 1, 1, 2], "expected": ["b20", "b21", "b22", "b23", "b24", "b25", "b26", "b27", "b28", "b29", "b40", "b41", "b42", "b43", "b44", "b45"]}, {"args": [[["p", 10, null], ["q", 10, null], ["r", 3, null]], 12, 0, 1, 0], "expected": ["q"]}, {"args": [[["a", 10, "gone"]], 10, 1, 0, 0], "expected": ["a"]}, {"args": [[], 5, 3, 3, 3], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-worst-rpo', 8, 'func', 'Худший RPO расписания', 'RPO — сколько данных (в минутах работы) можно потерять. Худшая потеря равна самому длинному промежутку между двумя успешными копиями. Дан список попыток attempts — пар [минута, успешна ли попытка] — и длина окна наблюдения window в минутах. Считайте, что на минуте 0 уже есть хорошая копия и что сбой может случиться вплоть до минуты window включительно. Учитывайте только успешные попытки с минутой от 0 до window. Напишите функцию worst_rpo(attempts, window): верните наибольший промежуток между соседними моментами из множества {0} ∪ {успешные попытки} ∪ {window}.', 'def worst_rpo(attempts, window):
    pass
', 'Отсортируйте минуты успешных попыток, добавьте 0 и window и найдите максимум разностей соседей.', '{"func": "worst_rpo", "tests": [{"args": [[], 1440], "expected": 1440}, {"args": [[[720, true]], 1440], "expected": 720}, {"args": [[[360, true], [720, true], [1080, true]], 1440], "expected": 360}, {"args": [[[360, true], [720, false], [1080, true]], 1440], "expected": 720}, {"args": [[[0, true], [1440, true]], 1440], "expected": 1440}, {"args": [[[100, false], [200, false]], 300], "expected": 300}, {"args": [[[500, true], [200, true], [900, true]], 1000], "expected": 400}, {"args": [[[2000, true], [-5, true], [30, true]], 120], "expected": 90}, {"args": [[], 0], "expected": 0}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-rto-path', 9, 'func', 'RTO по критическому пути', 'План восстановления состоит из шагов; шаги без зависимости друг от друга идут параллельно, а шаг начинается только после окончания всех шагов, от которых он зависит. Дан словарь steps: имя шага → [длительность в минутах, список имён шагов, от которых он зависит]. Зависимость от шага, которого нет в словаре, игнорируется. Циклов нет. Напишите функцию rto(steps): верните время восстановления в минутах — самый поздний момент окончания среди всех шагов (длину критического пути). Для пустого словаря верните 0.', 'def rto(steps):
    pass
', 'finish(n) = длительность n + максимум finish по зависимостям; запоминайте результаты в словаре.', '{"func": "rto", "tests": [{"args": [{}], "expected": 0}, {"args": [{"engine": [30, []]}], "expected": 30}, {"args": [{"storage": [20, []], "engine": [40, ["storage"]], "vms": [10, ["engine"]]}], "expected": 70}, {"args": [{"storage": [20, []], "network": [35, []], "engine": [15, ["storage"]], "vms": [10, ["engine", "network"]]}], "expected": 45}, {"args": [{"a": [5, []], "b": [7, ["a", "ghost"]], "c": [30, []], "d": [1, ["b", "c"]]}], "expected": 31}, {"args": [{"a": [0, []], "b": [0, ["a"]]}], "expected": 0}, {"args": [{"s1": [10, []], "s2": [10, ["s1"]], "s3": [10, ["s2"]], "x": [25, ["s1"]], "y": [1, ["x", "s3"]]}], "expected": 36}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-dr-mapping', 10, 'func', 'Проверка файла сопоставлений DR', 'Перед аварией проверяют файл сопоставлений. Даны: used — словарь «вид ресурса → список имён на основной площадке, которые используют машины» (виды, например, ''cluster'', ''domain'', ''network''); mapping — словарь «вид → список пар [имя на основной, имя на запасной]»; secondary — словарь «вид → список имён, которые реально есть на запасной площадке». Напишите функцию validate_mapping(used, mapping, secondary): верните отсортированный список без повторов строк-проблем. Виды проблем: ''unmapped:<вид>:<имя>'' — используемое имя не имеет ни одной пары; ''conflict:<вид>:<имя>'' — одно имя основной площадки сопоставлено двум и более разным именам запасной (проверяйте все пары mapping); ''missing_target:<вид>:<имя>'' — имя запасной площадки из пары отсутствует в secondary своего вида. Виды, которых нет в одном из словарей, считаются пустым списком.', 'def validate_mapping(used, mapping, secondary):
    pass
', 'Для каждого вида соберите словарь «основное имя → множество запасных»; три проверки — это три цикла по нему и по used.', '{"func": "validate_mapping", "tests": [{"args": [{"cluster": ["cl1"], "domain": ["d1", "d2"]}, {"cluster": [["cl1", "dr-cl1"]], "domain": [["d1", "dr-d1"], ["d2", "dr-d2"]]}, {"cluster": ["dr-cl1"], "domain": ["dr-d1", "dr-d2"]}], "expected": []}, {"args": [{"cluster": ["cl1", "cl2"]}, {"cluster": [["cl1", "dr-cl1"]]}, {"cluster": ["dr-cl1"]}], "expected": ["unmapped:cluster:cl2"]}, {"args": [{"network": ["net/ovirtmgmt"]}, {"network": [["net/ovirtmgmt", "net/mgmt-a"], ["net/ovirtmgmt", "net/mgmt-b"]]}, {"network": ["net/mgmt-a", "net/mgmt-b"]}], "expected": ["conflict:network:net/ovirtmgmt"]}, {"args": [{"domain": ["d1"]}, {"domain": [["d1", "dr-d9"]]}, {"domain": ["dr-d1"]}], "expected": ["missing_target:domain:dr-d9"]}, {"args": [{"cluster": ["cl1"]}, {}, {}], "expected": ["unmapped:cluster:cl1"]}, {"args": [{}, {"role": [["admin", "ops"]]}, {"role": ["admin"]}], "expected": ["missing_target:role:ops"]}, {"args": [{"cluster": ["cl1", "cl2"], "network": ["n1"]}, {"cluster": [["cl1", "x"], ["cl2", "x"]], "network": []}, {"cluster": ["x"], "network": ["n1"]}], "expected": ["unmapped:network:n1"]}, {"args": [{}, {}, {}], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-failover-order', 11, 'func', 'Порядок запуска при переходе', 'При аварийном переходе машины запускают по приоритету с учётом зависимостей. Дан словарь vms: имя → [приоритет, список имён, которые должны быть запущены раньше]. Меньшее число — более высокий приоритет. На каждом шаге из машин, все зависимости которых уже запущены, берётся одна с наименьшим (приоритет, имя). Зависимость от имени, которого нет в vms, игнорируется. Машины, которые не удалось запустить из-за циклической зависимости (или зависимости от такой машины), попадают в список blocked. Напишите функцию failover_order(vms): верните кортеж (порядок запуска, отсортированный список blocked).', 'def failover_order(vms):
    pass
', 'Алгоритм Кана с кучей: храните в куче пары (приоритет, имя) машин с нулевой степенью входа.', '{"func": "failover_order", "tests": [{"args": [{}], "expected": {"__tuple__": [[], []]}}, {"args": [{"web": [2, ["db"]], "db": [1, ["dns"]], "dns": [1, []]}], "expected": {"__tuple__": [["dns", "db", "web"], []]}}, {"args": [{"a": [3, []], "b": [1, []], "c": [2, []]}], "expected": {"__tuple__": [["b", "c", "a"], []]}}, {"args": [{"app": [1, ["db"]], "db": [5, []], "mon": [2, []], "cache": [3, []]}], "expected": {"__tuple__": [["mon", "cache", "db", "app"], []]}}, {"args": [{"x": [1, ["y"]], "y": [1, ["x"]], "z": [2, []], "w": [1, ["x"]]}], "expected": {"__tuple__": [["z"], ["w", "x", "y"]]}}, {"args": [{"a": [1, ["ghost"]], "b": [1, ["a", "a"]]}], "expected": {"__tuple__": [["a", "b"], []]}}, {"args": [{"s": [1, ["s"]], "t": [2, []]}], "expected": {"__tuple__": [["t"], ["s"]]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-split-ranges', 12, 'func', 'Нарезка диска на диапазоны', 'Диск размера size байт скачивают параллельно кусками. Напишите функцию split_ranges(size, chunk, align, max_ranges): верните список кортежей (начало, конец) с включённым концом, покрывающих байты 0..size-1 подряд и без пересечений. Размер куска c — chunk, округлённый вверх до кратного align. Если при таком c кусков получилось бы больше max_ranges, возьмите вместо него наименьшее c, кратное align и не меньшее ceil(size / max_ranges). Последний кусок может быть короче. При size <= 0 верните пустой список. Все числа положительные целые (кроме size).', 'def split_ranges(size, chunk, align, max_ranges):
    pass
', 'Округление вверх: -(-x // a) * a. Потом range(0, size, c) и min(s + c, size) - 1 для конца.', '{"func": "split_ranges", "tests": [{"args": [0, 100, 10, 5], "expected": []}, {"args": [-4, 100, 10, 5], "expected": []}, {"args": [100, 40, 10, 10], "expected": [{"__tuple__": [0, 39]}, {"__tuple__": [40, 79]}, {"__tuple__": [80, 99]}]}, {"args": [100, 35, 10, 10], "expected": [{"__tuple__": [0, 39]}, {"__tuple__": [40, 79]}, {"__tuple__": [80, 99]}]}, {"args": [100, 10, 10, 3], "expected": [{"__tuple__": [0, 39]}, {"__tuple__": [40, 79]}, {"__tuple__": [80, 99]}]}, {"args": [30, 7, 4, 100], "expected": [{"__tuple__": [0, 7]}, {"__tuple__": [8, 15]}, {"__tuple__": [16, 23]}, {"__tuple__": [24, 29]}]}, {"args": [4096, 1000, 512, 100], "expected": [{"__tuple__": [0, 1023]}, {"__tuple__": [1024, 2047]}, {"__tuple__": [2048, 3071]}, {"__tuple__": [3072, 4095]}]}, {"args": [10, 100, 1, 4], "expected": [{"__tuple__": [0, 9]}]}, {"args": [1000, 10, 10, 7], "expected": [{"__tuple__": [0, 149]}, {"__tuple__": [150, 299]}, {"__tuple__": [300, 449]}, {"__tuple__": [450, 599]}, {"__tuple__": [600, 749]}, {"__tuple__": [750, 899]}, {"__tuple__": [900, 999]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 24, 'ov24-reassembly', 13, 'func', 'Проверка собранного образа', 'После параллельной загрузки нужно убедиться, что образ собран без дыр и наложений. Размер образа size байт, принятые куски received — список пар [начало, конец] (конец включительно). Куски обрезаются по границам 0..size-1; кусок, оказавшийся целиком вне образа или с началом больше конца, игнорируется. Напишите функцию check_ranges(size, received): верните кортеж (gaps, overlaps), где gaps — отсортированный список кортежей (начало, конец) максимальных непрерывных участков, не покрытых ни одним куском, а overlaps — такой же список участков, покрытых двумя и более кусками. При size <= 0 верните ([], []).', 'def check_ranges(size, received):
    pass
', 'Метод разностного массива: событие +1 в начале куска и −1 после конца; идите по отсортированным границам и склеивайте соседние участки одного вида.', '{"func": "check_ranges", "tests": [{"args": [100, [[0, 49], [50, 99]]], "expected": {"__tuple__": [[], []]}}, {"args": [100, [[0, 29], [60, 99]]], "expected": {"__tuple__": [[{"__tuple__": [30, 59]}], []]}}, {"args": [100, [[0, 59], [40, 99]]], "expected": {"__tuple__": [[], [{"__tuple__": [40, 59]}]]}}, {"args": [100, [[0, 49], [70, 99], [45, 60]]], "expected": {"__tuple__": [[{"__tuple__": [61, 69]}], [{"__tuple__": [45, 49]}]]}}, {"args": [100, []], "expected": {"__tuple__": [[{"__tuple__": [0, 99]}], []]}}, {"args": [100, [[0, 99], [0, 99], [10, 20]]], "expected": {"__tuple__": [[], [{"__tuple__": [0, 99]}]]}}, {"args": [100, [[-10, 5], [95, 200], [300, 400], [50, 40]]], "expected": {"__tuple__": [[{"__tuple__": [6, 94]}], []]}}, {"args": [0, [[0, 5]]], "expected": {"__tuple__": [[], []]}}, {"args": [10, [[0, 3], [4, 6], [5, 9], [9, 9]]], "expected": {"__tuple__": [[], [{"__tuple__": [5, 6]}, {"__tuple__": [9, 9]}]]}}]}');
